using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Drawing;using System.Threading;using Prometheus;
class OverwriteTests024 {
 static List<string> checks=new List<string>();static void Check(bool value,string message){if(!value)throw new Exception("FAIL "+message);checks.Add(message);Console.WriteLine("PASS "+message);}static Clip Copy(Clip c){return Store.Json().Deserialize<Clip>(Store.Json().Serialize(Store.Fields(c)));}
 static void Main(string[] args){string root=Path.GetFullPath(args[0]);Tools.Root=Path.GetFullPath(args[1]);var token=CancellationToken.None;var image=Media.Inspect(Path.Combine(root,"solid023.png"),token);var e=new Editor();e.Commit(p=>{p.assets.Add(image);Media.Insert(p,image.id,p.Active.tracks.First(t=>t.kind=="video").id,0);p.Active.clips[0].duration=new Rational(10,1);});var baseProject=Store.Copy(e.Project);string oldId=e.Project.Active.clips[0].id;Action<double,double> overlay=(start,length)=>e.Commit(p=>{var clip=Copy(p.Active.clips[0]);clip.id=Store.Id();clip.timeline_start=Rational.Time(start);clip.duration=Rational.Time(length);clip.source_in=Rational.Time(0);p.Active.clips.Add(clip);Editor.Overwrite(p,new[]{clip.id});});
  string before=Store.Encode(e.Project);overlay(3,2);var ordered=e.Project.Active.clips.OrderBy(c=>c.timeline_start.Seconds).ToList();Check(ordered.Count==3&&ordered[0].duration.Seconds==3&&ordered[2].timeline_start.Seconds==5&&ordered[2].duration.Seconds==5&&ordered[2].source_in.Seconds==5,"middle overwrite retains both tails with correct source offset");e.Undo();Check(Store.Encode(e.Project)==before,"overwrite undo restores original ids and ranges");e.Redo();Check(e.Project.Active.clips.Count==3,"overwrite redo restores fragments");e.Reset(Store.Copy(baseProject));overlay(0,3);Check(e.Project.Active.clips.Count==2&&e.Project.Active.clips.Find(c=>c.id==oldId).source_in.Seconds==3,"overwrite beginning advances retained source");e.Reset(Store.Copy(baseProject));overlay(7,5);Check(e.Project.Active.clips.Count==2&&e.Project.Active.clips.Find(c=>c.id==oldId).duration.Seconds==7,"overwrite end retains prefix");e.Reset(Store.Copy(baseProject));overlay(0,10);Check(e.Project.Active.clips.Count==1&&!e.Project.Active.clips.Any(c=>c.id==oldId),"full overwrite removes covered clip");e.Reset(Store.Copy(baseProject));overlay(10,2);Check(e.Project.Active.clips.Count==2&&e.Project.Active.clips.Find(c=>c.id==oldId).duration.Seconds==10,"touching boundary does not remove a frame");e.Reset(Store.Copy(baseProject));overlay(1.0/60,10-2.0/60);Check(e.Project.Active.clips.Count==3&&e.Project.Active.clips.Count(c=>Math.Abs(c.duration.Seconds-1.0/60)<0.000001)==2,"one-frame tails are preserved");
  e.Reset(Store.Copy(baseProject));e.Commit(p=>{p.Active.clips[0].speed=new Rational(2,1);p.Active.clips[0].source_in=new Rational(1,1);});overlay(3,2);Check(e.Project.Active.clips.First(c=>c.timeline_start.Seconds==5).source_in.Seconds==11,"fragment source offset respects speed");
  e.Reset(Store.Copy(baseProject));overlay(12,2);var extending=e.Project.Active.clips.First(c=>c.id==oldId);e.Trim(extending.id,false,13);Check(e.Project.Active.clips.First(c=>c.timeline_start.Seconds==13).source_in.Seconds==1&&e.Project.Active.clips.First(c=>c.id==oldId).duration.Seconds==13,"trim extension overwrites only covered part of neighbor");
  var av=Media.Inspect(Path.Combine(root,"source.mp4"),token);var linked=new Editor();linked.Commit(p=>{p.assets.Add(av);Media.Insert(p,av.id,p.Active.tracks.First(t=>t.kind=="video").id,0);});var initial=Store.Copy(linked.Project);linked.Commit(p=>Media.Insert(p,av.id,p.Active.tracks.First(t=>t.kind=="video").id,0.5));Check(linked.Project.Active.link_groups.Count==2&&linked.Project.Active.link_groups.All(g=>g.clip_ids.Count==2),"linked insertion preserves paired prefix and new linked media");linked.Reset(Store.Copy(initial));var v=linked.Project.Active.clips.First(c=>linked.Project.Active.tracks.Find(t=>t.id==c.track_id).kind=="video");linked.Commit(p=>{var next=Copy(v);next.id=Store.Id();next.timeline_start=new Rational(1,2);next.duration=new Rational(1,2);p.Active.clips.Add(next);Editor.Overwrite(p,new[]{next.id});});Check(linked.Project.Active.clips.Count(c=>linked.Project.Active.tracks.Find(t=>t.id==c.track_id).kind=="audio")==1&&linked.Project.Active.link_groups.Count==0,"video-only overwrite retains audio and separates altered links");
  linked.Reset(Store.Copy(initial));linked.Commit(p=>p.Active.tracks.Find(t=>t.kind=="audio").locked=true);before=Store.Encode(linked.Project);try{linked.MoveSelection(new List<string>{v.id},v.id,1,null);}catch{}Check(Store.Encode(linked.Project)==before,"locked linked move is rejected atomically");
  var voice=Media.Inspect(Path.Combine(root,"voice.wav"),token);var sampleEditor=new Editor();sampleEditor.Commit(p=>{p.assets.Add(voice);Media.InsertAudioBatch(p,new List<Asset>{Media.Inspect(Path.Combine(root,"voice.wav"),token)},p.Active.tracks.First(t=>t.kind=="audio").id,0);p.Active.clips[0].duration=new Rational(10,48000);});sampleEditor.Commit(p=>{var clip=Copy(p.Active.clips[0]);clip.id=Store.Id();clip.timeline_start=new Rational(3,48000);clip.duration=new Rational(2,48000);p.Active.clips.Add(clip);Editor.Overwrite(p,new[]{clip.id});});Check(sampleEditor.Project.Active.clips.Count==3&&sampleEditor.Project.Active.clips.Any(c=>c.timeline_start.Seconds==5.0/48000&&c.source_in.Seconds==5.0/48000),"audio overwrite retains tails to sample precision");
  e.Reset(Store.Copy(baseProject));before=Store.Encode(e.Project);try{e.Commit(p=>{var first=Copy(p.Active.clips[0]);first.id=Store.Id();first.timeline_start=new Rational(2,1);first.duration=new Rational(2,1);var second=Copy(first);second.id=Store.Id();p.Active.clips.Add(first);p.Active.clips.Add(second);Editor.Overwrite(p,new[]{first.id,second.id});});}catch{}Check(Store.Encode(e.Project)==before,"conflicting incoming clips reject whole operation without partial overwrite");
  e.Reset(Store.Copy(baseProject));e.Commit(p=>{foreach(double start in new[]{12.0,16.0}){var clip=Copy(p.Active.clips[0]);clip.id=Store.Id();clip.timeline_start=Rational.Time(start);clip.duration=new Rational(2,1);p.Active.clips.Add(clip);}});var moving=e.Project.Active.clips.Where(c=>c.timeline_start.Seconds>=12).ToList();e.MoveSelection(moving.Select(c=>c.id).ToList(),moving[0].id,2,null);Check(e.Project.Active.clips.Count==5&&e.Project.Active.clips.Find(c=>c.id==moving[1].id).timeline_start.Seconds==6,"multi move subtracts union of incoming intervals and preserves gaps");
  e.Reset(Store.Copy(baseProject));e.Commit(p=>{var next=Copy(p.Active.clips[0]);next.id=Store.Id();next.timeline_start=new Rational(12,1);next.duration=new Rational(2,1);p.Active.clips.Add(next);});var movingClip=e.Project.Active.clips.Last();e.MoveSelection(new List<string>{movingClip.id},movingClip.id,4,null);Store.Save(e.Project,Path.Combine(root,"overwrite024.prometheus.json"));Check(Store.Load(Path.Combine(root,"overwrite024.prometheus.json")).Active.clips.Count==3,"overwrite fragments save and reopen with valid references");
  string blue=Path.Combine(root,"blue024.png");using(var bitmap=new Bitmap(64,36)){using(var graphics=Graphics.FromImage(bitmap))graphics.Clear(Color.Blue);bitmap.Save(blue,System.Drawing.Imaging.ImageFormat.Png);}var blueAsset=Media.Inspect(blue,token);e.Reset(Store.Copy(baseProject));e.Commit(p=>{p.Active.clips[0].duration=new Rational(1,1);p.assets.Add(blueAsset);var next=Copy(p.Active.clips[0]);next.id=Store.Id();next.asset_id=blueAsset.id;next.stream_id=blueAsset.streams[0].id;next.timeline_start=new Rational(1,4);next.duration=new Rational(1,2);p.Active.clips.Add(next);Editor.Overwrite(p,new[]{next.id});});using(var frame=Rendering.Frame(e.Project,0.25,token))Check(frame.GetPixel(320,180).B>200,"preview displays incoming image at overwrite start");using(var frame=Rendering.Frame(e.Project,0.75,token))Check(frame.GetPixel(320,180).R>170,"preview restores original right fragment at overwrite end");Rendering.Export(e.Project,Path.Combine(root,"overwrite024.mp4"),token);Check(File.Exists(Path.Combine(root,"overwrite024.mp4")),"overwritten montage exports successfully");File.WriteAllText(Path.Combine(root,"checks-overwrite024.json"),Store.Json().Serialize(new{status="PASS",checks=checks}));
 }
}
